per_question_execution.agent_sql:
SELECT ?gender (COUNT(?p) AS ?n)
WHERE {
  ?p a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient/gender> ?gender .
}
GROUP BY ?gender

SELECT ?condition_name (COUNT(?c) AS ?n)
WHERE {
  ?c a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Condition> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Condition/condition_name> ?condition_name .
}
GROUP BY ?condition_name
ORDER BY DESC(?n)
LIMIT 5

SELECT ?city (COUNT(?p) AS ?patientCount) WHERE {
  ?p a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient/city> ?city .
}
GROUP BY ?city
ORDER BY DESC(?patientCount)
LIMIT 3

SELECT ?encounter_class (COUNT(?encounter) AS ?n)
WHERE {
  ?encounter a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Encounter> ;
             <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Encounter/encounter_class> ?encounter_class .
}
GROUP BY ?encounter_class

SELECT ?status (COUNT(?m) AS ?n)
WHERE {
  ?m a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Medication> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Medication/status> ?status .
}
GROUP BY ?status

SELECT (COUNT(?e) AS ?n) WHERE {
  ?e a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Encounter> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Encounter/patient_ref> ?pref .
  ?p a <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient> ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient/id> ?pid ;
     <http://snowflake-fhir_r4-ontology-20260813-030435/ontology/vkg-snowflake_fhir_r4/Patient/gender> ?gender .
  FILTER(?gender = "female")
  BIND(CONCAT("urn:uuid:", ?pid) AS ?uref)
  FILTER(?pref = ?uref)
}

